code='''import itertools,time,networkx as nx,json,sympy as s

def graphs_degseq(ds):
 n=len(ds); adj=[set() for _ in ds]; rem=list(ds)
 def rec(i):
  if i==n:
   yield [(a,b) for a in range(n) for b in adj[a] if a<b];return
  d=rem[i]
